local L = select(2, ...).L

L["crest.alterac.description"] = "Una torre rota en un pico frío. El reino ya no existe. Los arroyos siguen siendo buenos."
L["crest.alterac.name"] = "La torre rota"
L["crest.arathi.description"] = "Viejas piedras erguidas sobre la hierba de las tierras altas, más viejas que cualquiera que discuta sobre ellas."
L["crest.arathi.name"] = "Las piedras erguidas"
L["crest.ashenvale.description"] = "Un fuego fatuo que flota entre árboles oscuros. El bosque se fija en cada pescador que se queda demasiado."
L["crest.ashenvale.name"] = "El fuego fatuo"
L["crest.azshara.description"] = "Una columna de un viejo imperio, con el mar trepando por ella. Algo aún nada en esas ruinas."
L["crest.azshara.name"] = "La columna caída"
L["crest.badlands.description"] = "Un arco de piedra que el viento tardó diez mil años en terminar. Trae tu propia agua."
L["crest.badlands.name"] = "El arco de piedra"
L["crest.barrens.description"] = "Un árbol de copa plana en las llanuras secas. Cada oasis de por allí es el rincón favorito de alguien."
L["crest.barrens.name"] = "La acacia"
L["crest.blackrock.description"] = "Una montaña negra con fuego en las grietas y cadenas en la puerta. Pesca en los pozos de lava bajo tu propia responsabilidad."
L["crest.blackrock.name"] = "La aguja negra"
L["crest.blastedlands.description"] = "Una puerta de piedra negra con fuego verde dentro. Nadie pesca allí por las vistas."
L["crest.blastedlands.name"] = "La puerta en llamas"
L["crest.burningsteppes.description"] = "Una montaña en llamas bajo un cielo de ceniza. El agua está tan caliente que se podría guisar en ella."
L["crest.burningsteppes.name"] = "El pico en llamas"
L["crest.darkshore.description"] = "Una media luna sobre agua gris, para los pescadores que pescan cuando ha oscurecido."
L["crest.darkshore.name"] = "La media luna"
L["crest.darnassus.description"] = "Un pozo de brillo plateado bajo un gran árbol. El lago que lo rodea guarda los peces de la ciudad."
L["crest.darnassus.name"] = "El pozo de plata"
L["crest.deadwind.description"] = "Una torre alta en un valle muerto. Las charcas están tranquilas. Demasiado, dicen algunos, y se van."
L["crest.deadwind.name"] = "La torre solitaria"
L["crest.desolace.description"] = "Un gran cráneo con cuernos, de un viejo cementerio. La costa es más amable que el interior."
L["crest.desolace.name"] = "El cráneo astado"
L["crest.dunmorogh.description"] = "Cuernos enroscados sobre un campo nevado. Los carneros de allí arriba tienen opiniones sobre los forasteros."
L["crest.dunmorogh.name"] = "El carnero"
L["crest.durotar.description"] = "Un escórpido sobre tierra roja. La costa es mejor compañía que los escórpidos."
L["crest.durotar.name"] = "El escórpido"
L["crest.duskwood.description"] = "Dos ojos entre árboles negros. Allí los pescadores mantienen el farol encendido y el sedal corto."
L["crest.duskwood.name"] = "Ojos en el bosque"
L["crest.dustwallow.description"] = "Un farol que quedó encendido en la choza de un pescador, entre la niebla del pantano."
L["crest.dustwallow.name"] = "El farol"
L["crest.easternplague.description"] = "Una pequeña capilla que sostiene su luz frente a la plaga. A su lado hay buena agua."
L["crest.easternplague.name"] = "La capilla"
L["crest.elwynn.description"] = "El primer lago que vieron casi todos los pescadores, y el roble bajo el que se sentaron."
L["crest.elwynn.name"] = "El viejo roble"
L["crest.felwood.description"] = "Un árbol retorcido con fuego verde en las venas. Lava todo lo que pesques allí. Dos veces."
L["crest.felwood.name"] = "El árbol corrupto"
L["crest.feralas.description"] = "Agua que cae entre los árboles gigantes, para los pescadores que eligen el camino largo."
L["crest.feralas.name"] = "Las cascadas"
L["crest.hillsbrad.description"] = "Tres manzanas de los huertos al pie de las colinas. Las truchas bajo el molino engordan con la fruta caída."
L["crest.hillsbrad.name"] = "Tres manzanas"
L["crest.hinterlands.description"] = "Grandes plumas de las colinas salvajes, donde las aves grandes anidan sobre los ríos."
L["crest.hinterlands.name"] = "Tres plumas"
L["crest.hyjal.description"] = "Un brote verde que surge de viejas brasas. La montaña se está curando, y sus arroyos con ella."
L["crest.hyjal.name"] = "El brote"
L["crest.hyjalcrater.description"] = "Agua quieta en un anillo roto de piedra negra. Aquí ardió algo una vez; el lago no ha dicho nada."
L["crest.hyjalcrater.name"] = "El lago del cráter"
L["crest.ironforge.description"] = "Un yunque ante la forja de la montaña. Ahí debajo hay un lago, y los enanos lo pescan."
L["crest.ironforge.name"] = "El yunque"
L["crest.lochmodan.description"] = "Una presa que contiene un lago de las tierras altas. Los enanos la hicieron para durar, y ha durado."
L["crest.lochmodan.name"] = "La gran presa"
L["crest.lordamere.description"] = "Una isla boscosa en un lago ancho y gris, con una barca varada en la orilla. Agua tranquila, y mucha."
L["crest.lordamere.name"] = "La isla del lago"
L["crest.moonglade.description"] = "Una cornamenta sobre un lago quieto, bajo la luna. Un lugar tranquilo, y tranquilo a propósito."
L["crest.moonglade.name"] = "La cornamenta"
L["crest.mulgore.description"] = "Un tótem tallado en las llanuras de hierba alta, donde los arroyos bajan claros de las colinas."
L["crest.mulgore.name"] = "El tótem"
L["crest.orgrimmar.description"] = "Una puerta erizada de pinchos en un cañón rojo. Los estanques de la ciudad son más hondos de lo que parecen."
L["crest.orgrimmar.name"] = "La puerta de pinchos"
L["crest.redridge.description"] = "Tres picos rojos que se alzan en un lago de montaña, y cada uno reflejado."
L["crest.redridge.name"] = "Tres picos"
L["crest.riverglades.description"] = "Una barcaza en un río sinuoso entre colinas verdes. Allí el comercio llega por agua, y los peces también."
L["crest.riverglades.name"] = "La barcaza"
L["crest.searinggorge.description"] = "Un crisol que vierte oro fundido. Pescar allí es pescar en lava, así que trae paciencia y una caña larga."
L["crest.searinggorge.name"] = "El crisol"
L["crest.shendralas.description"] = "Un libro abierto sobre un pedestal roto, guardado por gente que nunca dejó de leer."
L["crest.shendralas.name"] = "El tomo abierto"
L["crest.silithus.description"] = "Un escarabajo sobre la arena del desierto. Allí los lagos son pequeños y sospechosos."
L["crest.silithus.name"] = "El escarabajo"
L["crest.silverpine.description"] = "Pinos plateados en la orilla de un lago oscuro. Casi todas las noches algo aúlla ahí fuera."
L["crest.silverpine.name"] = "Pinos de plata"
L["crest.stonetalon.description"] = "Una gran garra aferrada a una piedra. Agua de montaña, fría y rápida."
L["crest.stonetalon.name"] = "La garra"
L["crest.stormwind.description"] = "Murallas blancas y una puerta sobre los canales. La ciudad pesca en sus propias aguas, con educación."
L["crest.stormwind.name"] = "El torreón blanco"
L["crest.stranglethorn.description"] = "Un pez que salta limpio sobre las olas de la selva, como si se hubiera enterado del torneo."
L["crest.stranglethorn.name"] = "El salto"
L["crest.swampofsorrows.description"] = "El tejado de un templo asomando del agua del pantano. Lo que hay debajo, debajo se queda."
L["crest.swampofsorrows.name"] = "El santuario ahogado"
L["crest.tanaris.description"] = "Un sol del desierto sobre la única sombra en leguas: la orilla."
L["crest.tanaris.name"] = "El sol del desierto"
L["crest.teldrassil.description"] = "Un árbol tan alto que su copa está entre las estrellas. Sus raíces beben de un agua muy antigua."
L["crest.teldrassil.name"] = "La corona de estrellas"
L["crest.thousandneedles.description"] = "Agujas de piedra que se alzan de la llanura. Pesca a su sombra, y no te quites el sombrero."
L["crest.thousandneedles.name"] = "Las agujas"
L["crest.thunderbluff.description"] = "Una meseta alta con una tienda en la cima. Las pozas de abajo recogen las cascadas, y los peces con ellas."
L["crest.thunderbluff.name"] = "La meseta"
L["crest.tirisfal.description"] = "Un murciélago ante una luna enfermiza. Hasta los peces de allí parecen algo cansados."
L["crest.tirisfal.name"] = "El murciélago"
L["crest.undercity.description"] = "Una corona rota sobre canales verdes. La corte ya no existe. Los canales aún tienen peces."
L["crest.undercity.name"] = "La corona rota"
L["crest.ungoro.description"] = "Una huella del tamaño de un bote de remos. El cráter tiene preocupaciones mayores que los peces."
L["crest.ungoro.name"] = "La huella"
L["crest.veiledsea.description"] = "Un barco medio perdido en un banco de niebla marina. Aquí los peces suben de muy hondo, y todo lo demás también."
L["crest.veiledsea.name"] = "El banco de niebla"
L["crest.westernplague.description"] = "Un cuervo en un árbol muerto sobre campos vacíos. Los granjeros se fueron. Los peces no."
L["crest.westernplague.name"] = "El cuervo"
L["crest.westfall.description"] = "Aspas girando sobre el camino de la costa. El mar está más cerca de lo que admiten los granjeros."
L["crest.westfall.name"] = "El molino"
L["crest.wetlands.description"] = "El ancla de un puerto, sacada del fango. Aún huele un poco a él."
L["crest.wetlands.name"] = "El ancla"
L["crest.winterspring.description"] = "Un copo de nieve sobre agua quieta, donde pescar en el hielo es pescar de verdad."
L["crest.winterspring.name"] = "La escarcha"
L["crest.zephras.description"] = "Una isla que flota sobre las nubes, con su barco amarrado a la piedra. El agua queda muy abajo."
L["crest.zephras.name"] = "La isla flotante"
L["family.1.name"] = "Pargo de barro"
L["family.2.name"] = "Bagre"
L["family.3.name"] = "Cola amarilla"
L["family.4.name"] = "Agallarroja"
L["family.5.name"] = "Salmón"
L["family.6.name"] = "Langosta"
L["family.7.name"] = "Pez poderoso"
L["ledgergood.ledger.binding.abyssal.description"] = "Negro como el agua profunda, con un brillo pálido que se enrosca bajo la superficie. Para pescadores que han bajado al fondo diez veces y han vuelto."
L["ledgergood.ledger.binding.abyssal.name"] = "Negro abisal"
L["ledgergood.ledger.binding.carapace.description"] = "El caparazón de un cangrejo que se creía más grande que la barca, y casi lo era. Aún mantiene las páginas cerradas a pellizcos."
L["ledgergood.ledger.binding.carapace.name"] = "Caparazón de cangrejo"
L["ledgergood.ledger.binding.ember.description"] = "Escamas de algo que vivió demasiado cerca de la forja, aún calientes por dentro. No la dejes en la mesilla de noche."
L["ledgergood.ledger.binding.ember.name"] = "Escama de ascua"
L["ledgergood.ledger.binding.flywallet.description"] = "Lona encerada con un vellón delante, y en el vellón las moscas que funcionaron. Las que no, están en el fondo del lago."
L["ledgergood.ledger.binding.flywallet.name"] = "Cartera de moscas"
L["ledgergood.ledger.binding.heartwood.description"] = "Dos tablas de roble viejo, un pez tallado hondo en la tapa y una hiedra que nadie plantó y a la que no hay forma de convencer de que se vaya."
L["ledgergood.ledger.binding.heartwood.name"] = "Duramen tallado"
L["ledgergood.ledger.binding.iridescent.description"] = "Escamas de todos los colores que el agua ha soltado alguna vez, una sobre otra. Nunca se ve igual dos veces."
L["ledgergood.ledger.binding.iridescent.name"] = "Escama iridiscente"
L["ledgergood.ledger.binding.keeper.description"] = "Vitela crema casi enterrada en oro. Reservada al pescador cuyo libro ya no tiene nada por encontrar."
L["ledgergood.ledger.binding.keeper.name"] = "Oro del custodio"
L["ledgergood.ledger.binding.knit.description"] = "Una cubierta tejida con la misma lana que el jersey del pescador, botones de trenca incluidos. Huele un poco a lluvia y abriga más de lo que tiene derecho."
L["ledgergood.ledger.binding.knit.name"] = "Punto de ochos"
L["ledgergood.ledger.binding.lacquer.description"] = "Treinta capas de laca negra, dos koi en oro y un lomo cosido con seda roja. Lleva un año hacerla y un segundo llenarla de huellas."
L["ledgergood.ledger.binding.lacquer.name"] = "Koi en laca negra"
L["ledgergood.ledger.binding.legend.description"] = "Cuero azul repujado con escamas y, en la tapa, tres peces dorados persiguiéndose por el mismo círculo."
L["ledgergood.ledger.binding.legend.name"] = "Tres peces dorados"
L["ledgergood.ledger.binding.level10.description"] = "Una piel más clara y suave, gastada en las esquinas por unas cuantas temporadas de pulgares mojados."
L["ledgergood.ledger.binding.level10.name"] = "Piel curtida"
L["ledgergood.ledger.binding.level20.description"] = "Cuero azul oscuro con filetes de plata, del color de un puerto al anochecer."
L["ledgergood.ledger.binding.level20.name"] = "Azul de marea"
L["ledgergood.ledger.binding.level30.description"] = "Cuero verde oscuro, dorados del color del junco seco y un leve olor a ribera."
L["ledgergood.ledger.binding.level30.name"] = "Verde junco"
L["ledgergood.ledger.binding.level40.description"] = "Cuero rojo oscuro y dorado abundante. La sangre de pescado apenas se nota."
L["ledgergood.ledger.binding.level40.name"] = "Sangre de buey"
L["ledgergood.ledger.binding.level50.description"] = "Cuero gris pizarra con hierros de plata, para los días en que nadie más sale."
L["ledgergood.ledger.binding.level50.name"] = "Gris tormenta"
L["ledgergood.ledger.binding.level60.description"] = "Cuero casi negro y oro brillante. Un libro de pescador no llega a ser mucho más fino."
L["ledgergood.ledger.binding.level60.name"] = "La de Nat"
L["ledgergood.ledger.binding.logbook.description"] = "Tapas de lona y esquinas de becerro, una brújula engastada en la cubierta y una correa contra los rociones. La mancha de agua venía de regalo."
L["ledgergood.ledger.binding.logbook.name"] = "Bitácora del capitán"
L["ledgergood.ledger.binding.monster.description"] = "Piel escamosa de algo que no quería que lo sacaran, cerrada con uno de sus propios dientes."
L["ledgergood.ledger.binding.monster.name"] = "Piel de monstruo"
L["ledgergood.ledger.binding.stormglass.description"] = "Tapas de hierro, bisagras de pletina y una ventana con una tormenta dentro. Nadie recuerda haber metido el pez ahí."
L["ledgergood.ledger.binding.stormglass.name"] = "Relicario de tormenta"
L["ledgergood.ledger.binding.wave.description"] = "Tafilete azul con una gran ola grabada, la cresta realzada en oro. En algún punto de su ladera va un bote muy pequeño."
L["ledgergood.ledger.binding.wave.name"] = "Ola rompiente"
L["ledgergood.ledger.soundset.choir.description"] = "Voces graves que suben del agua profunda, y algo muy grande que canta con ellas desde abajo."
L["ledgergood.ledger.soundset.choir.name"] = "Coro de las profundidades"
L["ledgergood.ledger.soundset.concertina.description"] = "Una frase de concertina de una canción marinera que todos se saben a medias, tocada por alguien que se la sabe entera."
L["ledgergood.ledger.soundset.concertina.name"] = "Concertina de lobo de mar"
L["ledgergood.ledger.toaststyle.blueprint.description"] = "Trazado en el taller entre otros tres inventos y un pequeño incendio. Escala uno a uno, tolerancias opcionales, pesca garantizada (no garantizada)."
L["ledgergood.ledger.toaststyle.blueprint.name"] = "Plano del manitas"
L["ledgergood.ledger.toaststyle.cartographer.description"] = "Una carta que nunca se termina. Cada agua que te sabes de memoria está entintada: costa, colinas, sondas mar adentro. El resto sigue a lápiz, esperando."
L["ledgergood.ledger.toaststyle.cartographer.name"] = "Folio del cartógrafo"
L["ledgergood.ledger.toaststyle.crier.description"] = "Leído en la plaza a mediodía, entre el precio del pan y el caballero al que armaron caballero. Todo verdad, dedo arriba, dedo abajo."
L["ledgergood.ledger.toaststyle.crier.name"] = "Bando del pregonero"
L["ledgergood.ledger.toaststyle.deep.description"] = "Escrito con la única luz del fondo del lago. Algo ahí abajo sujeta la presa entre los dientes y no tiene prisa por soltarla."
L["ledgergood.ledger.toaststyle.deep.name"] = "Señuelo abisal"
L["ledgergood.ledger.toaststyle.drum.description"] = "Tensado sobre un bastidor junto al fuego, pintado con la mano del clan y golpeado tan fuerte que despierta al valle de al lado. Un golpe por cada pez digno de contarse."
L["ledgergood.ledger.toaststyle.drum.name"] = "Tambor del clan"
L["ledgergood.ledger.toaststyle.gala.description"] = "La noche del gran torneo, cuando todo el puerto cuelga sus luces y nadie se va a casa antes de los fuegos artificiales. Esta es para los pescadores que trajeron los tres."
L["ledgergood.ledger.toaststyle.gala.name"] = "Gala del gran torneo"
L["ledgergood.ledger.toaststyle.glade.description"] = "Escrito a la luz de la luna junto a un estanque sagrado, donde el agua recuerda todo lo que ha nadado en ella. Los fuegos fatuos vinieron a leer por encima de tu hombro."
L["ledgergood.ledger.toaststyle.glade.name"] = "Claro estrellado"
L["ledgergood.ledger.toaststyle.glass.description"] = "Una ventana de una capilla junto al agua, emplomada a mano. Las palabras van en el único cristal transparente; el resto es rubí, cobalto y el color de la última luz."
L["ledgergood.ledger.toaststyle.glass.name"] = "Vidriera de capilla"
L["ledgergood.ledger.toaststyle.hall.description"] = "Tallado en la roca viva bajo la montaña e incrustado por un herrero que midió dos veces y presumió tres. Las runas mantienen caliente la forja."
L["ledgergood.ledger.toaststyle.hall.name"] = "Salón de la montaña"
L["ledgergood.ledger.toaststyle.hex.description"] = "Atado por un médico brujo en una isla donde los peces devuelven el mordisco. La máscara ha visto tu futuro: más peces. La máscara ha visto cosas peores."
L["ledgergood.ledger.toaststyle.hex.name"] = "Maleficio de la selva"
L["ledgergood.ledger.toaststyle.ice.description"] = "Un palmo de buen hielo negro, un agujero y mucha espera. Cuando sube la bandera corres, y el frío te da igual."
L["ledgergood.ledger.toaststyle.ice.name"] = "A través del hielo"
L["ledgergood.ledger.toaststyle.koi.description"] = "Un rollo de un pintor que solo pintó peces, y los pintó bien. El círculo alrededor de la captura le llevó un solo aliento."
L["ledgergood.ledger.toaststyle.koi.name"] = "Tinta y koi"
L["ledgergood.ledger.toaststyle.legend.description"] = "Para las piezas que se discuten en el muelle durante años. Borde dorado, seda azul y un sello como es debido."
L["ledgergood.ledger.toaststyle.legend.name"] = "Historia de pescador"
L["ledgergood.ledger.toaststyle.lion.description"] = "Tallada en la piedra blanca de una ciudad portuaria que nunca deja de construir, y sellada bajo el león de sus reyes. Los estandartes solo ondean por una pieza digna de trompetas."
L["ledgergood.ledger.toaststyle.lion.name"] = "Carta del león"
L["ledgergood.ledger.toaststyle.prestige.description"] = "Vitela color sangre de buey y laureles dorados, para un pescador que volvió a empezar y lo hizo todo otra vez."
L["ledgergood.ledger.toaststyle.prestige.name"] = "Vitela sangre de buey"
L["ledgergood.ledger.toaststyle.shroud.description"] = "Arrancado de la tela con la que te enterraron, y vuelto a coser cuando saliste a pescar. A la presa no le importa. La presa no lo sabe."
L["ledgergood.ledger.toaststyle.shroud.name"] = "Sudario"
L["ledgergood.ledger.toaststyle.slate.description"] = "Escrita con tiza esta mañana, sobre hielo a mediodía. El precio es lo que el pescadero crea que puedes aguantar."
L["ledgergood.ledger.toaststyle.slate.name"] = "Pizarra del pescadero"
L["ledgergood.ledger.toaststyle.stitch.description"] = "Bordado por alguien paciente en las largas noches entre temporadas. Cada pez le llevó una velada; la aguja sigue clavada."
L["ledgergood.ledger.toaststyle.stitch.name"] = "Dechado a punto de cruz"
L["ledgergood.ledger.toaststyle.totem.description"] = "Pintado sobre una piel junto a un fuego, bajo un cielo enorme, por alguien que cree que cada pez es un regalo de la Tierra. Da las gracias."
L["ledgergood.ledger.toaststyle.totem.name"] = "Tótem de las llanuras"
L["ledgergood.ledger.toaststyle.trophy.description"] = "Nogal, latón y cuatro buenos tornillos. De esas cosas que se cuelgan sobre la chimenea y se señalan el resto de la velada."
L["ledgergood.ledger.toaststyle.trophy.name"] = "Trofeo de pared"
L["ledgergood.ledger.toaststyle.warband.description"] = "Forjada bajo un cielo rojo en una ciudad hecha de hierro y rencores. Los braseros arden por el clan; los zarpazos son para quien dudó de la captura."
L["ledgergood.ledger.toaststyle.warband.name"] = "Hueste de hierro"
L["legend.19803.blurb"] = "La mayoría de los pescadores solo llega a ver su estela. Este frenó lo justo para dejarse sacar."
L["legend.19803.title"] = "Cazacorredores"
L["legend.19805.blurb"] = "Demasiado guapo para la mesa de un torneo, y parece saberlo."
L["legend.19805.title"] = "Rival de Keefer"
L["legend.19806.blurb"] = "Se comporta como la realeza y pelea como si tuviera una corona que perder."
L["legend.19806.title"] = "Cazarreinas"
L["line.uncaughtjunk.text"] = "El pedestal está limpio y listo. La pieza se retrasa."
L["line.uncaughtlegend.text"] = "Algunos peces solo se pescan muy de vez en cuando. Esta página espera a uno."
L["line.uncaughttreasure.text"] = "Algo sellado, aún sin encontrar."
L["line.unchartedwaters.text"] = "Aguas sin catalogar. Aún no hay mapa de estas."
L["prestigeframe.castoff.description"] = "La borda de un bote de tingladillo, con tres capas de pintura, y los remos recogidos encima."
L["prestigeframe.castoff.name"] = "Soltando amarras"
L["prestigeframe.constellation.description"] = "Pasado el décimo, te ponen en el cielo: un pescador de estrellas con caña y sedal, y un pez en la punta. Una estrella más en la corona por cada Prestigio de Maestro."
L["prestigeframe.constellation.name"] = "La constelación del pescador"
L["prestigeframe.coral.description"] = "Un anillo de nácar en un arrecife: coral rojo por un lado, un abanico de mar por el otro y siempre alguien que pasa nadando."
L["prestigeframe.coral.name"] = "Los jardines de coral"
L["prestigeframe.dive.description"] = "Un casco de buzo de cobre, atornillado y lleno de aire. El pescador ha saltado por la borda para mirar al pez a los ojos."
L["prestigeframe.dive.name"] = "La inmersión"
L["prestigeframe.jetty.description"] = "Tablones del viejo embarcadero, atados en un anillo, que aún huelen a brea y a marea baja."
L["prestigeframe.jetty.name"] = "El embarcadero"
L["prestigeframe.leviathan.description"] = "La serpiente del fondo de toda historia de marineros, enroscada en un anillo de oro viejo con la cola en la boca."
L["prestigeframe.leviathan.name"] = "El leviatán"
L["prestigeframe.lighthouse.description"] = "La linterna al final del cabo, toda de cristal, con la luz saliendo sobre el agua."
L["prestigeframe.lighthouse.name"] = "El faro"
L["prestigeframe.midnight.description"] = "Cristal negro de donde no baja la luz, iluminado por lo que vive allí. Una de esas cosas se ha interesado."
L["prestigeframe.midnight.name"] = "La zona de medianoche"
L["prestigeframe.none.description"] = "Un anillo de tinta, y una conjetura a lápiz de lo que irá alrededor."
L["prestigeframe.none.name"] = "Sin escribir"
L["prestigeframe.opensea.description"] = "Una rosa de los vientos de la carta de un navegante, cada rumbo exacto y el norte coronado en oro."
L["prestigeframe.opensea.name"] = "Mar abierto"
L["prestigeframe.starward.description"] = "Donde se acaba el mar empieza el cielo: una esfera armilar de oro y plata bajo la noche, y los peces viejos entre las estrellas."
L["prestigeframe.starward.name"] = "El mar de las estrellas"
L["prestigeframe.storm.description"] = "El timón de un queche en plena galerna: caoba, latón y ocho buenas cabillas, y el cielo deshaciéndose encima."
L["prestigeframe.storm.name"] = "La tormenta"
L["species.12238.blurb"] = "Ancho, lento y gris como la costa que le da nombre. Hace mejor guiso que primera impresión."
L["species.12238.riddle"] = "Mar gris bajo árboles viejos y la luna, o muy al sur, en el desierto."
L["species.13422.blurb"] = "Los armeros pagan bien las escamas. La anguila no está de acuerdo con el trato."
L["species.13422.riddle"] = "Un enjambre que se retuerce en mar hondo, frente a las costas más salvajes."
L["species.13754.blurb"] = "Tan pesado que algunos pescadores lo pescan sentados."
L["species.13754.riddle"] = "Mar abierto frente a las costas lejanas, lo bastante hondo para los pesados."
L["species.13755.blurb"] = "Llega con la escarcha. Más brazos de los que un pescador puede desenredar con calma."
L["species.13755.riddle"] = "Orillas cálidas, cuando el año se vuelve frío."
L["species.13756.blurb"] = "Aparece con los días largos y se va con el primer viento frío."
L["species.13756.riddle"] = "Orillas cálidas en la mitad cálida del año."
L["species.13757.blurb"] = "Hace cosquillas. No la lamas."
L["species.13757.riddle"] = "Un chisporroteo en aguas lejanas y salvajes, del alba a bien entrada la noche."
L["species.13758.blurb"] = "Agallas como brasas. Muerde como si fuera en serio."
L["species.13758.riddle"] = "Aguas de interior de las tierras más salvajes, de día o de noche."
L["species.13759.blurb"] = "Come a la luz de las estrellas. Quien lo quiere aprende a llevarse bien con la oscuridad."
L["species.13759.riddle"] = "Aguas salvajes lejos de las orillas mansas, después de ponerse el sol."
L["species.13760.blurb"] = "Sale con el sol y trasnocha. Nadie sabe adónde va antes del alba."
L["species.13760.riddle"] = "Ríos y lagos lejanos, cálidos o fríos, mientras dura la luz del día."
L["species.13888.blurb"] = "Pellizca primero y no pregunta nunca."
L["species.13888.riddle"] = "Aguas rocosas y profundas en los confines del mundo."
L["species.13889.blurb"] = "Pálido como la escarcha. Mejor comerlo el día que se pesca, cosa que rara vez es posible."
L["species.13889.riddle"] = "Las aguas más lejanas que hay, de lagos helados a colinas abrasadas."
L["species.13890.blurb"] = "Lleva la armadura por fuera y el genio por dentro. Trae un cuchillo más pesado."
L["species.13890.riddle"] = "Algo pesado en las aguas más lejanas, después de ponerse el sol."
L["species.13893.blurb"] = "El primo grande. Te harán falta las dos manos y, probablemente, un amigo."
L["species.13893.riddle"] = "Aguas hondas frente a una costa lejana y olvidada."
L["species.1467.blurb"] = "Un pez pequeño y alegre, sin idea de cuántos cocineros lo están esperando."
L["species.1467.riddle"] = "Un lago sereno entre colinas, en tierra de granjas bien asentadas."
L["species.16967.blurb"] = "Grande, rápido y buen bocado. Casi todos se pescan como favor para otro, lo que parece un desperdicio."
L["species.16967.riddle"] = "Un río ancho entre bosque húmedo y enmarañado, en el lejano oeste."
L["species.16968.blurb"] = "Se lanza al cebo como si llevara todo el día esperando una discusión."
L["species.16968.riddle"] = "Una orilla gris y triste en una costa del oeste, seca y vacía."
L["species.16969.blurb"] = "Esa vela es de adorno, y lo sabe. Pelea como si tuviera público."
L["species.16969.riddle"] = "Bajíos cálidos de selva, donde el mar llega hasta los mismos árboles."
L["species.16970.blurb"] = "Vistoso como un pájaro de la selva y el doble de problemático en el sedal."
L["species.16970.riddle"] = "Bajíos cálidos y turbios donde un pantano se junta con el mar."
L["species.19807.blurb"] = "Pez de torneo. Sabe a victoria, o al menos a una larga tarde intentándolo."
L["species.19807.riddle"] = "Solo mientras dura el gran torneo de la selva."
L["species.19975.blurb"] = "Huele exactamente como promete el nombre. Alguien, en algún sitio, aún quiere una docena."
L["species.19975.riddle"] = "Agua parda y revuelta, en lo más hondo de la selva humeante."
L["species.21071.blurb"] = "Huele a las colinas junto a las que nada."
L["species.21071.riddle"] = "Pequeños bancos en colinas y bosques, con un leve olor a hierbas."
L["species.21153.blurb"] = "La salvia se ha hecho mayor."
L["species.21153.riddle"] = "Bancos más nutridos con aroma a hierbas, en colinas nevadas y selva humeante."
L["species.251524.blurb"] = "Nuevo en estas aguas, y nadie sabe muy bien cómo llegó."
L["species.251524.riddle"] = "Bancos nuevos y vistosos en un lago tranquilo de las colinas del este."
L["species.4603.blurb"] = "Rápido, vistoso y muy satisfecho de sí mismo."
L["species.4603.riddle"] = "Costas saladas al norte y al sur, a ambos lados del mar."
L["species.6289.blurb"] = "Muerde cualquier cosa, incluida, una vez, la bota de un gnomo."
L["species.6289.riddle"] = "Ríos perezosos en las tierras donde empiezan los héroes."
L["species.6291.blurb"] = "Pequeño, brillante y en todas partes. Todo cuaderno de pescador empieza aquí, y nadie confiesa cuántos devolvió al agua."
L["species.6291.riddle"] = "Lo primero que tira del sedal de un novato, en las aguas más mansas de todas."
L["species.6299.blurb"] = "Mala pinta, peor olor, y cocinado da algo que comería un raptor."
L["species.6299.riddle"] = "Agua gris y cansada en el norte sombrío, a ambos lados del mar."
L["species.6303.blurb"] = "Lo bastante escurridizo para ganarse el nombre. Frito queda mejor de lo que tiene derecho."
L["species.6303.riddle"] = "Costas someras, donde vadean los aventureros recién llegados."
L["species.6308.blurb"] = "Todo bigotes y rencor. Se enfurruña en el fondo hasta que decide pelear."
L["species.6308.riddle"] = "Ríos turbios a ambos lados del mar."
L["species.6317.blurb"] = "Lo bautizaron los enanos, que nombran todo según cómo se porta cuando intentas sujetarlo."
L["species.6317.riddle"] = "Aguas frías y quietas de las tierras altas, en país de enanos."
L["species.6358.blurb"] = "Los alquimistas quieren el aceite. Los cocineros no quieren saber nada de él."
L["species.6358.riddle"] = "Un banco que deja una película brillante sobre las aguas de la costa."
L["species.6359.blurb"] = "Caliente al tacto, incluso fuera del agua."
L["species.6359.riddle"] = "Bancos en remolino del color de las brasas, frente a costas del norte y del sur."
L["species.6361.blurb"] = "Los colores se apagan menos de una hora después de sacarlo. Míralo deprisa."
L["species.6361.riddle"] = "Costa abierta, algo más lejos de la orilla de lo que acostumbras."
L["species.6362.blurb"] = "Terco en el sedal, dulce en el plato."
L["species.6362.riddle"] = "Costas del norte brumoso al sur caluroso, donde el fondo cae de golpe."
L["species.6458.blurb"] = "Más que un pez, una advertencia sobre el agua. Lávalo dos veces y piénsatelo otra vez."
L["species.6458.riddle"] = "Agua sucia donde los goblins perforan colinas y llanuras resecas."
L["species.6522.blurb"] = "Cómelo bajo tu propia responsabilidad. No hay dos pescadores que lo probaran y cuenten igual la hora siguiente."
L["species.6522.riddle"] = "Bancos extraños en las llanuras secas, donde el agua misma parece enferma."
L["species.8365.blurb"] = "La cabeza brilla de verdad. No, no es mitril. Deja de preguntarle al herrero."
L["species.8365.riddle"] = "Lagos y ríos de tierras más ásperas, del bosque espeso al desierto pelado."
L["sub.13874.plaque"] = "Demasiado pesada para flotar y para cargarla lejos. Alguien probó las dos cosas."
L["sub.13875.plaque"] = "Reforzado con hierro y con cerradura, por si acaso. Lo de dentro merecía la inquietud."
L["sub.13881.plaque"] = "Demasiado glotón para dejar de comer, y demasiado lleno para escapar nadando."
L["sub.13918.plaque"] = "Reforzado, con cerradura, y hundido igualmente. Hay cargamentos sin un respiro."
L["sub.20708.plaque"] = "Tan bien sellado que el agua nunca entró. Por lo visto, el dueño tampoco."
L["sub.21113.plaque"] = "Estanco, como se prometió. Nadie prometió que flotara."
L["sub.21150.plaque"] = "El hierro aguantó. El barco del que cayó, no."
L["sub.21162.plaque"] = "Hinchado, resbaladizo y lleno de la suerte de otro. Lávate las manos después."
L["sub.21164.plaque"] = "Terco hasta el final. Solo soltó lo que se había tragado a punta de cuchillo."
L["sub.21228.plaque"] = "Reforzado con mitril. Quien lo llenó esperaba problemas, y los tuvo."
L["sub.21243.plaque"] = "Lo bastante grande para tragarse una bolsa entera, y lo hizo."
L["sub.6297.plaque"] = "Donado por el agua. Dueño desconocido, y mejor que siga así."
L["sub.6301.plaque"] = "Fue de un carretero. Todavía parece estar esperando una carreta."
L["sub.6307.plaque"] = "La tinta se corrió hace mucho. El corcho, hay que reconocérselo, aguantó."
L["sub.6351.plaque"] = "Se cayó una vez, por lo que se ve, y luego otra por si acaso."
L["sub.6352.plaque"] = "Embalada para una travesía en seco. No la tuvo."
L["sub.6353.plaque"] = "Lo bastante pequeño para perderse por la borda. Alguien lo demostró."
L["sub.6354.plaque"] = "Pequeño, con cerradura, y más difícil de abrir de lo que nunca fue de cargar."
L["sub.6355.plaque"] = "Hecho para resistirlo todo. El mar lleva tiempo poniéndolo a prueba."
L["sub.6356.plaque"] = "Alguien lo cerró, alguien lo hundió, y ninguno volvió a por él."
L["sub.6357.plaque"] = "Sellada a conciencia contra el agua. El agua tuvo paciencia."
L["sub.6455.plaque"] = "Adónde fue la carreta sigue bajo investigación."
L["sub.6456.plaque"] = "Se ruega no tocar la pieza expuesta."
L["sub.6457.plaque"] = "Un gnomo diría que esto 'casi funciona'."
L["sub.6643.plaque"] = "Un pez pequeño con mucho apetito y ninguna idea de qué cuenta como comida."
L["sub.6645.plaque"] = "Mordió algo demasiado grande para tragárselo, y se lo tragó igual."
L["sub.6647.plaque"] = "Comía del fondo, donde acaba todo lo que se le cae a cualquiera."
L["sub.6717.plaque"] = "Repuestos de un manitas, caídos por la borda a mitad de faena. Jura que el barco ya hacía agua."
L["sub.6718.plaque"] = "Piezas de un reclamo de pato de relojería, de los que explotan. Lejos de los patos de verdad."
L["sub.7973.plaque"] = "No dice nada de lo que lleva dentro. Ábrela igualmente; a veces hay una perla."
L["sub.8366.plaque"] = "Se comió algo brillante. Quizá hasta mitril, esta vez."
L["title.complete.junk.text"] = "Coleccionista de botas"
L["title.complete.ledger.text"] = "Pescador de Azeroth"
L["title.complete.treasure.text"] = "Custodio de cargas perdidas"
L["title.complete.trophy.text"] = "Peso pesado"
L["title.complete.varieties.text"] = "Custodio de todos los colores"
L["title.level1.text"] = "Alevín"
L["title.level10.text"] = "Aficionado"
L["title.level20.text"] = "Lanzasedal"
L["title.level30.text"] = "Buena caña"
L["title.level40.text"] = "Lobo de mar"
L["title.level50.text"] = "Lector de mareas"
L["title.level60.text"] = "Colega de Nat"
L["title.prestige1.text"] = "Marea que vuelve"
L["title.prestige10.text"] = "Pleamar"
L["title.prestige5.text"] = "Resaca"
